"Floating Ink שומר גרסה לפני שמתחילים לערוך, ועוד אחת כל חצי שעה של כתיבה. אפשר גם לשמור גרסה בעצמך.": "يحفظ Floating Ink إصدارًا قبل أن تبدأ التعديل، وإصدارًا آخر كل نصف ساعة من الكتابة. يمكنك أيضًا حفظ إصدار بنفسك.",
