"חיבור ל-AI: קלוד עובד איתך בתוך Floating Ink": "ربط الذكاء الاصطناعي: Claude يعمل معك داخل Floating Ink",
"כאן יופיעו ההודעות של קלוד ומה שהוא עושה במסמכים.": "ستظهر هنا رسائل Claude وما يفعله في مستنداتك.",
"כבוי. כדי שקלוד יוכל לעבוד כאן, מסמנים את התיבה למעלה.": "متوقف. ليتمكن Claude من العمل هنا، حدّد المربع في الأعلى.",
"כשהחיבור פתוח, קלוד יכול לקרוא ולשנות את המסמכים כאן, ומה שהוא קורא נשלח אליו כמו כל הודעה שכותבים לו. כל שינוי אפשר לבטל עם Ctrl+Z.": "عندما يكون الاتصال مفعّلاً، يستطيع Claude قراءة المستندات هنا وتغييرها، وما يقرؤه يُرسَل إليه مثل أي رسالة تكتبها له. يمكنك التراجع عن أي تغيير بالضغط على Ctrl+Z.",
"לאפשר ל-AI לעבוד ב-Floating Ink": "السماح للذكاء الاصطناعي بالعمل في Floating Ink",
"לפני שכתוב של עוזר": "قبل إعادة الكتابة من المساعد",
"מורידים את המחבר של Floating Ink:": "نزّل موصّل Floating Ink:",
"מחובר! אפשר לבקש מקלוד לעבוד ב-Floating Ink.": "متصل! يمكنك أن تطلب من Claude العمل في Floating Ink.",
"מחכה למחבר של Floating Ink במחשב… אם עוד לא התקנת אותו, ההוראות למטה.": "في انتظار موصّل Floating Ink على الكمبيوتر… إذا لم تثبّته بعد، فالخطوات في الأسفل.",
"מסמנים כאן למעלה את התיבה. אם הדפדפן שואל אם לאפשר גישה לאפליקציות במחשב, מאשרים.": "حدّد المربع في الأعلى هنا. إذا سألك المتصفح عن السماح بالوصول إلى التطبيقات على الجهاز، فاسمح بذلك.",
"פתיחה": "فتح",
"באפליקציית Claude שבמחשב: הגדרות ← Plugins (תוספים) ← Add ← Upload plugin, ובוחרים את הקובץ שירד.": "في تطبيق Claude على الكمبيوتر: الإعدادات ← Plugins ← Add ← Upload plugin، ثم اختر الملف الذي نزّلته.",
"קלוד מקשיב עכשיו — מה שכותבים כאן יגיע אליו מיד.": "كلود يستمع الآن — ما تكتبه هنا يصل إليه فورًا.",
"כדי שקלוד יענה כאן, כותבים לו בשיחה איתו: תתחבר ל-Floating Ink.": "لكي يجيبك كلود هنا، اكتب له في محادثتك معه: اتصل بـ Floating Ink.",
"פותחים שיחה עם קלוד וכותבים לו: תתחבר ל-Floating Ink. מכאן הוא עונה בחלונית הזאת.": "افتح محادثة مع كلود واكتب له: اتصل بـ Floating Ink. من الآن فصاعدًا يجيبك في هذه النافذة.",
