"קלוד מחובר עכשיו לחלון אחר של Floating Ink. כדי לעבוד מהחלון הזה, מכבים ומדליקים את התיבה למעלה.": "كلود متصل الآن بنافذة أخرى من Floating Ink. للعمل من هذه النافذة، ألغِ تحديد المربع أعلاه ثم حدّده من جديد.",
"Floating Ink ינסה שוב בעוד כמה דקות.": "سيحاول Floating Ink مرة أخرى بعد بضع دقائق.",
"Floating Ink ינסה שוב בעוד כמה דקות. אפשר גם לנסות עכשיו.": "سيحاول Floating Ink مرة أخرى بعد بضع دقائق. يمكنك أيضًا المحاولة الآن.",
"Floating Ink יפסיק לשמור עותקים בתיקייה. הגיבויים שכבר נשמרו בה יישארו שם.": "سيتوقف Floating Ink عن حفظ النسخ في المجلد. النسخ الاحتياطية المحفوظة فيه ستبقى هناك.",
"{0} (מגיבוי)": "{0} (من النسخة الاحتياطية)",
"אולי היא הועברה או נמחקה. אפשר לבחור אותה שוב, או תיקייה אחרת.": "ربما تم نقله أو حذفه. يمكنك اختياره مرة أخرى، أو اختيار مجلد آخر.",
"אולי היא הועברה או נמחקה. לחיצה כאן כדי לבחור אותה שוב.": "ربما تم نقله أو حذفه. انقر هنا لاختياره مرة أخرى.",
"אי אפשר לגבות לתיקייה הזאת. כדאי לבחור תיקייה אחרת, למשל בתוך \"מסמכים\" או OneDrive.": "لا يمكن النسخ الاحتياطي إلى هذا المجلد. اختر مجلدًا آخر، مثلًا داخل \"المستندات\" أو OneDrive.",
"אין מסמכים בקובץ הגיבוי הזה": "لا توجد مستندات في ملف النسخة الاحتياطية هذا",
"בגיבוי יש גרסה חדשה יותר": "الإصدار في النسخة الاحتياطية أحدث",
"בוחרים פעם אחת תיקייה במחשב, ומאז Floating Ink שומר בה לבד עותק של כל המסמכים, המצגות והתמונות, כמה דקות אחרי כל שינוי.": "اختر مجلدًا على الكمبيوتر مرة واحدة، ومن بعدها يحفظ Floating Ink فيه تلقائيًا نسخة من كل المستندات والعروض التقديمية والصور، بعد بضع دقائق من كل تغيير.",
"בחירת הכל": "تحديد الكل",
"בחירת תיקייה": "اختيار مجلد",
"בלי אישור אי אפשר לשמור בתיקייה. אפשר לבחור תיקייה אחרת, או להוריד קובץ גיבוי.": "بدون إذن لا يمكن الحفظ في المجلد. يمكنك اختيار مجلد آخر، أو تنزيل ملف نسخة احتياطية.",
