"הדפדפן הזה לא יכול לגבות לבד לתיקייה. כדאי להוריד קובץ גיבוי פעם בשבוע ולשמור אותו במקום בטוח, כמו OneDrive או Google Drive. אם יעבור שבוע בלי גיבוי, Floating Ink יזכיר לך.": "هذا المتصفح لا يستطيع النسخ الاحتياطي إلى مجلد تلقائيًا. من الأفضل تنزيل ملف نسخة احتياطية مرة في الأسبوع وحفظه في مكان آمن، مثل OneDrive أو Google Drive. إذا مر أسبوع بدون نسخة احتياطية، سيذكّرك Floating Ink.",
"הדפדפן צריך אישור כדי להמשיך לשמור בתיקייה. בחלון שלו כדאי לבחור לאשר בכל ביקור, ואז זה לא יישאל שוב.": "يحتاج المتصفح إلى إذنك لمواصلة الحفظ في المجلد. في نافذته اختر السماح في كل زيارة، ولن يسألك مرة أخرى.",
