"אין חיבור לאינטרנט. השינויים יעברו כשהחיבור יחזור.": "لا يوجد اتصال بالإنترنت. ستنتقل التغييرات عند عودة الاتصال.",
"אין כאן חדר משותף כרגע.": "لا توجد غرفة مشتركة هنا حاليًا.",
"בואו לערוך איתי מסמך ב-Floating Ink. הקוד: {0}": "تعالوا حرّروا معي مستندًا في Floating Ink. الرمز: {0}",
"בואו לערוך איתי מצגת ב-Floating Ink. הקוד: {0}": "تعالوا حرّروا معي عرضًا تقديميًا في Floating Ink. الرمز: {0}",
"בלי הרשמה ובלי חשבון. מה שכותבים עובר ישירות בין המכשירים, מוצפן, ולא נשמר באף שרת.": "بدون تسجيل وبدون حساب. ما تكتبونه ينتقل مباشرة بين الأجهزة، مشفّرًا، ولا يُحفظ على أي خادم.",
"הוזמנת לחדר {0}. איך יקראו לך בחדר?": "دُعيت إلى الغرفة {0}. ما الاسم الذي سنناديك به في الغرفة؟",
"החדר {0} כבר פתוח אצלך בחלון אחר. אפשר להיכנס אליו גם מכאן, כמשתתף נוסף.": "الغرفة {0} مفتوحة لديك بالفعل في نافذة أخرى. يمكنك الانضمام إليها من هنا أيضًا، كمشارك إضافي.",
"החדר הזה כבר נסגר.": "هذه الغرفة مغلقة بالفعل.",
"החדר הזה פתוח בחלון אחר של Floating Ink.": "هذه الغرفة مفتوحة في نافذة أخرى من Floating Ink.",
"החדר המשותף: מי כאן, הקוד והקישור": "الغرفة المشتركة: من هنا، والرمز والرابط",
"החדר נסגר": "الغرفة مغلقة",
"החדר נסגר. כל מי שהיה בו נשאר עם עותק משלו.": "أُغلقت الغرفة. كل من كان فيها احتفظ بنسخته الخاصة.",
"החדר פתוח. אפשר לשלוח לחברים את הקוד או את הקישור.": "الغرفة مفتوحة. يمكنك إرسال الرمز أو الرابط لأصدقائك.",
"הכינוי שלך": "اسمك المستعار",
"המסמך יישאר אצלך, אבל השינויים כבר לא יעברו בינך לבין האחרים.": "سيبقى المستند لديك، لكن التغييرات لن تنتقل بعد الآن بينك وبين الآخرين.",
"המצגת תישאר אצלך, אבל השינויים כבר לא יעברו בינך לבין האחרים.": "سيبقى العرض التقديمي لديك، لكن التغييرات لن تنتقل بعد الآن بينك وبين الآخرين.",
"העתקה": "نسخ",
