"הפסקה הזאת בעריכה אצל {0}. אפשר לכתוב בה כשיעצרו לרגע.": "هذه الفقرة قيد التحرير من قبل {0}. يمكنك الكتابة فيها بعد توقف قصير.",
"הקוד הועתק": "تم نسخ الرمز",
"הקוד צריך להיות 6 תווים: אותיות באנגלית ומספרים.": "يجب أن يتكوّن الرمز من 6 أحرف: حروف إنجليزية وأرقام.",
"הקישור הועתק": "تم نسخ الرابط",
