"הקישור לחדר לא שלם. כדאי לבקש אותו שוב.": "رابط الغرفة غير مكتمل. من الأفضل طلبه مرة أخرى.",
"התיבה הזאת בעריכה אצל {0}": "هذا المربع قيد التحرير من قبل {0}",
"התיבה שכתבת בה נמחקה": "تم حذف المربع الذي كنت تكتب فيه",
"זה לוקח בדרך כלל כמה שניות.": "هذا يستغرق عادةً بضع ثوانٍ.",
"חברים שיקבלו את הקוד יערכו איתך את המסמך הזה.": "الأصدقاء الذين يحصلون على الرمز سيحررون هذا المستند معك.",
"חברים שיקבלו את הקוד יערכו איתך את המצגת הזאת.": "الأصدقاء الذين يحصلون على الرمز سيحررون هذا العرض التقديمي معك.",
"חדר משותף": "غرفة مشتركة",
"חדר משותף: עובדים ביחד בזמן אמת": "غرفة مشتركة: العمل معًا في الوقت الفعلي",
"יצאת מהחדר. המסמך נשאר אצלך.": "غادرت الغرفة. بقي المستند لديك.",
"יצאת מהחדר. המצגת נשארה אצלך.": "غادرت الغرفة. بقي العرض التقديمي لديك.",
"יציאה": "مغادرة",
"יציאה מהחדר": "مغادرة الغرفة",
"כדאי לבדוק את הקוד, ושמי שפתח את החדר עדיין מחובר. אפשר גם להמשיך לחכות כאן.": "من الأفضل التأكد من الرمز، ومن أنّ من فتح الغرفة ما زال متصلًا. يمكنك أيضًا الاستمرار في الانتظار هنا.",
"כדאי לכתוב כינוי, כדי שכולם ידעו מי זה.": "من الأفضل كتابة اسم مستعار، حتى يعرف الجميع مَن أنت.",
"כל מי שבחדר יישאר עם עותק משלו של המסמך, והשינויים כבר לא יעברו ביניכם.": "كل من في الغرفة سيحتفظ بنسخته الخاصة من المستند، ولن تنتقل التغييرات بعد الآن بينكم.",
"כל מי שבחדר יישאר עם עותק משלו של המצגת, והשינויים כבר לא יעברו ביניכם.": "كل من في الغرفة سيحتفظ بنسخته الخاصة من العرض التقديمي، ولن تنتقل التغييرات بعد الآن بينكم.",
"כניסה": "انضمام",
"כניסה לחדר": "الانضمام إلى الغرفة",
"כשיוצאים מהחדר, או כשמי שפתח אותו סוגר אותו, המסמך נשאר אצלך במכשיר.": "عندما تغادر الغرفة، أو عندما يُغلقها من فتحها، يبقى المستند لديك على جهازك.",
"כשיוצאים מהחדר, או כשמי שפתח אותו סוגר אותו, המצגת נשארת אצלך במכשיר.": "عندما تغادر الغرفة، أو عندما يُغلقها من فتحها، يبقى العرض التقديمي لديك على جهازك.",
"כשסוגרים את החדר, כל מי שהיה בו נשאר עם עותק משלו של המסמך.": "عند إغلاق الغرفة، يحتفظ كل من كان فيها بنسخته الخاصة من المستند.",
"כשסוגרים את החדר, כל מי שהיה בו נשאר עם עותק משלו של המצגת.": "عند إغلاق الغرفة، يحتفظ كل من كان فيها بنسخته الخاصة من العرض التقديمي.",
"לא הצלחתי להעתיק. אפשר לסמן ולהעתיק בעצמך.": "لم أتمكن من النسخ. يمكنك التحديد والنسخ بنفسك.",
"לא הצלחתי להתחבר ישירות לאחד המשתתפים. זה קורה ברשתות מסוימות, למשל בגלישה סלולרית. כדאי לנסות רשת Wi-Fi.": "لم أتمكن من الاتصال مباشرة بأحد المشاركين. يحدث هذا في بعض الشبكات، مثل بيانات الجوال. من الأفضل تجربة شبكة Wi-Fi.",
"לא הצלחתי לטעון את רכיב החיבור. כדאי לבדוק את האינטרנט ולרענן את הדף.": "لم أتمكن من تحميل مكوّن الاتصال. من الأفضل التحقق من الإنترنت وتحديث الصفحة.",
"לא הצלחתי לשמור במכשיר הזה.": "لم أتمكن من الحفظ على هذا الجهاز.",
"לא מצאתי אף אחד בחדר {0}.": "لم أجد أحدًا في الغرفة {0}.",
"למישהו בחדר יש גרסה אחרת של Floating Ink. כדאי שכולם ירעננו את הדף.": "لدى أحد في الغرفة إصدار مختلف من Floating Ink. من الأفضل أن يحدّث الجميع الصفحة.",
"למשל: נועה": "مثال: سارة",
"מה שכותבים עובר ישירות בין המכשירים שבחדר, מוצפן, ולא נשמר באף שרת. רק מי שיש לו את הקוד יכול להיכנס.": "ما تكتبونه ينتقل مباشرة بين الأجهزة الموجودة في الغرفة، مشفّرًا، ولا يُحفظ على أي خادم. فقط من يملك الرمز يمكنه الانضمام.",
"מחכה שחברים ייכנסו. אפשר לשלוח להם את הקוד או את הקישור.": "بانتظار انضمام الأصدقاء. يمكنك إرسال الرمز أو الرابط لهم.",
"מי בחדר": "من في الغرفة",
"מי שפתח את החדר": "من فتح هذه الغرفة",
"מי שפתח את החדר סגר אותו. המסמך נשאר אצלך במכשיר, ואפשר להמשיך לעבוד עליו לבד.": "مَن فتح الغرفة أغلقها. بقي المستند لديك على جهازك، ويمكنك متابعة العمل عليه بمفردك.",
