"כשמשנים מספר, כל הנוסחאות שמשתמשות בו מתעדכנות לבד. גוררים את הריבוע הקטן בפינת התא כדי להעתיק נוסחה לתאים שליד, והכתובות בה זזות איתה. $ לפני אות או מספר (כמו $B$2) משאיר אותם קבועים; F4 מוסיף אותו.": "عندما تغيّر رقمًا، تتحدث كل الصيغ التي تستخدمه تلقائيًا. اسحب المربع الصغير في زاوية الخلية لنسخ صيغة إلى الخلايا المجاورة، وتتحرك العناوين معها. علامة $ قبل الحرف أو الرقم (مثل $B$2) تُبقيه ثابتًا، وF4 يضيفها.",
"כתובת של תא היא אות של עמודה ומספר של שורה. במקום להקליד אותה, אפשר ללחוץ על התא בזמן שכותבים": "عنوان الخلية هو حرف العمود ورقم الصف. بدلًا من كتابته، يمكنك النقر على الخلية أثناء الكتابة",
