"בואו לערוך איתי גיליון ב-Floating Ink. הקוד: {0}": "تعال نعدّل جدول بيانات معًا في Floating Ink. الرمز: {0}",
"דפים של PDF עוד אי אפשר לערוך ביחד. אפשר לפתוח חדר ממסמך, ממצגת או מגיליון.": "لا يمكن تحرير صفحات PDF معًا بعد. يمكنك فتح غرفة من مستند أو عرض تقديمي أو جدول بيانات.",
"הגיליון הזה גדול מדי לחדר משותף: יש בו יותר מ-{0} תאים מלאים.": "جدول البيانات هذا كبير جدًا على غرفة مشتركة: فيه أكثر من {0} خلية ممتلئة.",
"הגיליון יישאר אצלך, אבל השינויים כבר לא יעברו בינך לבין האחרים.": "سيبقى جدول البيانات معك، لكن التغييرات لن تنتقل بعد الآن بينك وبين الآخرين.",
"התא הזה בעריכה אצל {0}": "{0} يحرّر هذه الخلية الآن",
"התא שכתבת בו נמחק": "حُذفت الخلية التي كنت تكتب فيها",
"חברים שיקבלו את הקוד יערכו איתך את הגיליון הזה.": "يمكن للأصدقاء الذين يحصلون على الرمز تحرير جدول البيانات هذا معك.",
"יצאת מהחדר. הגיליון נשאר אצלך.": "خرجت من الغرفة. يبقى جدول البيانات معك.",
"כדי לפתוח חדר, פותחים קודם מסמך, מצגת או גיליון משלך.": "لفتح غرفة، افتح أولًا مستندًا أو عرضًا تقديميًا أو جدول بيانات خاصًا بك.",
"כל מי שבחדר יישאר עם עותק משלו של הגיליון, והשינויים כבר לא יעברו ביניכם.": "سيحتفظ كل من في الغرفة بنسخته الخاصة من جدول البيانات، ولن تنتقل التغييرات بينكم بعد الآن.",
"כשיוצאים מהחדר, או כשמי שפתח אותו סוגר אותו, הגיליון נשאר אצלך במכשיר.": "عندما تخرج من الغرفة، أو عندما يغلقها من فتحها، يبقى جدول البيانات على جهازك.",
"כשסוגרים את החדר, כל מי שהיה בו נשאר עם עותק משלו של הגיליון.": "عند إغلاق الغرفة، يحتفظ كل من كان فيها بنسخته الخاصة من جدول البيانات.",
"מי שפתח את החדר סגר אותו. הגיליון נשאר אצלך במכשיר, ואפשר להמשיך לעבוד עליו לבד.": "أغلق من فتح الغرفة الغرفةَ. يبقى جدول البيانات على جهازك، ويمكنك مواصلة العمل عليه وحدك.",
"מקבל את הגיליון…": "جارٍ استلام جدول البيانات…",
"עובדים ביחד על אותו מסמך, מצגת או גיליון, בזמן אמת: כל שינוי מופיע מיד אצל כולם.": "اعملوا معًا على المستند أو العرض التقديمي أو جدول البيانات نفسه، في الوقت الفعلي: يظهر كل تغيير فورًا لدى الجميع.",
"אין עדיין מספרים לגרף הזה": "لا توجد أرقام لهذا المخطط بعد",
