"יש כאן עוד הרבה פונקציות, כמו באקסל. הכפתור fx שליד שורת הנוסחאות מציג את כולן, עם חיפוש ועם דוגמה לכל אחת.": "توجد هنا دوال أخرى كثيرة، كما في Excel. زر fx بجانب شريط الصيغة يعرضها كلها، مع بحث ومثال لكل واحدة.",
"תוצאות שנשפכות לתאים": "نتائج تمتد إلى الخلايا",
"פונקציות כמו SORT, FILTER ו-UNIQUE מחזירות כמה ערכים, והם ממלאים לבד את התאים שמתחת ולצד הנוסחה. אם יש שם כבר משהו, מופיע #SPILL!": "دوال مثل SORT وFILTER وUNIQUE تعيد عدة قيم، فتملأ وحدها الخلايا تحت الصيغة وبجانبها. إذا كان هناك شيء بالفعل، يظهر #SPILL!",
"שגיאות כמו באקסל: #DIV/0! חילוק באפס, #VALUE! חשבון עם טקסט, #REF! תא שנמחק, #NAME? פונקציה שלא קיימת כאן, #N/A ערך שלא נמצא בחיפוש, #SPILL! אין מקום לתוצאות שנשפכות.": "أخطاء كما في Excel: #DIV/0! قسمة على صفر، #VALUE! حساب مع نص، #REF! خلية تم حذفها، #NAME? دالة غير موجودة هنا، #N/A قيمة لم يجدها البحث، #SPILL! لا مكان للنتائج الممتدة.",
