"{0} שניות": "{0} ثانية",
"אין מספיק זיכרון במכשיר בשביל עוד שכבות או פריימים בגודל הזה. אפשר למחוק שכבות או פריימים, או לבחור קנבס קטן יותר.": "لا توجد ذاكرة كافية في الجهاز لمزيد من الطبقات أو الإطارات بهذا الحجم. يمكنك حذف طبقات أو إطارات، أو اختيار لوحة رسم أصغر.",
"אין מקום בזיכרון של המכשיר לעוד שכבה. התמונה נכנסת לשכבה שבחרת.": "لا مكان في ذاكرة الجهاز لطبقة أخرى. ستوضع الصورة في الطبقة التي اخترتها.",
"אנימציה כסרטון MP4, למשל ליוטיוב": "الرسم المتحرك كفيديو MP4، ليوتيوب مثلًا",
"אנימציה כתמונה שזזה לבד, לשליחה ולשיתוף": "الرسم المتحرك كصورة تتحرك وحدها، للإرسال والمشاركة",
"אפשר למזג רק שתי שכבות נעוצות, או שתי שכבות שאינן נעוצות.": "يمكن دمج طبقتين مثبتتين فقط، أو طبقتين غير مثبتتين.",
"באנימציה צריך להיות לפחות פריים אחד": "يجب أن يحتوي الرسم المتحرك على إطار واحد على الأقل",
"בלולאה": "في حلقة",
"הדפדפן הזה לא יודע ליצור סרטונים. אפשר לשמור כ-GIF.": "هذا المتصفح لا يستطيع إنشاء مقاطع فيديو. يمكنك الحفظ كـ GIF.",
"הזזה אחורה": "نقل إلى الخلف",
"הזזה קדימה": "نقل إلى الأمام",
