"כדי לנגן צריך לפחות שני פריימים. \"פריים חדש\" מוסיף אחד.": "للتشغيل تحتاج إلى إطارين على الأقل. \"إطار جديد\" يضيف واحدًا.",
"כדי לשמור אנימציה צריך לפחות שני פריימים. \"פריים חדש\" בלשונית אנימציה מוסיף אחד.": "لحفظ رسم متحرك تحتاج إلى إطارين على الأقل. \"إطار جديد\" في تبويب الرسوم المتحركة يضيف واحدًا.",
